    /// Helper: write a rect (top, left, bottom, right) at addr.
    fn write_rect(
        bus: &mut impl MemoryBus,
        addr: u32,
        top: i16,
        left: i16,
        bottom: i16,
        right: i16,
    ) {
        bus.write_word(addr, top as u16);
        bus.write_word(addr + 2, left as u16);
        bus.write_word(addr + 4, bottom as u16);
        bus.write_word(addr + 6, right as u16);
    }

    /// Helper: read a rect from addr, returning (top, left, bottom, right).
    fn read_rect(bus: &impl MemoryBus, addr: u32) -> (i16, i16, i16, i16) {
        (
            bus.read_word(addr) as i16,
            bus.read_word(addr + 2) as i16,
            bus.read_word(addr + 4) as i16,
            bus.read_word(addr + 6) as i16,
        )
    }

    #[test]
    fn qd_extensions_generated_routes_preserve_exact_long_values() {
        assert_eq!(super::QD_EXTENSIONS_OPERATION_ROUTES.len(), 23);
        assert!(super::QD_EXTENSIONS_OPERATION_ROUTES
            .windows(2)
            .all(|pair| pair[0].selector < pair[1].selector));

        for (selector, routine_name) in [
            (0x0004_0001, "LockPixels"),
            (0x0004_0002, "UnlockPixels"),
            (0x0004_0004, "DisposeGWorld"),
            (0x0004_0007, "CTabChanged"),
            (0x0004_0008, "PixPatChanged"),
            (0x0004_0009, "PortChanged"),
            (0x0004_000A, "GDeviceChanged"),
            (0x0004_000B, "AllowPurgePixels"),
            (0x0004_000C, "NoPurgePixels"),
            (0x0004_000D, "GetPixelsState"),
            (0x0004_000F, "GetPixBaseAddr"),
            (0x0004_0011, "DisposeScreenBuffer"),
            (0x0004_0012, "GetGWorldDevice"),
            (0x0004_0013, "QDDone"),
            (0x0004_0016, "PixMap32Bit"),
            (0x0004_0017, "GetGWorldPixMap"),
            (0x0008_0005, "GetGWorld"),
            (0x0008_0006, "SetGWorld"),
            (0x0008_000E, "SetPixelsState"),
            (0x000E_0010, "NewScreenBuffer"),
            (0x000E_0015, "NewTempScreenBuffer"),
            (0x0016_0000, "NewGWorld"),
            (0x0016_0003, "UpdateGWorld"),
        ] {
            let route =
                super::qd_extensions_operation_route(0xAB1D, selector).expect("QDExtensions route");
            assert_eq!(route.routine_name, routine_name);
        }

        for (trap_word, selector) in [
            (0xAA1D, 0x0004_0001),
            (0xAB1D, 0x0000_0001),
            (0xAB1D, 0x0005_0001),
            (0xAB1D, 0x0004_000E),
            (0xAB1D, 0x0000_0014),
            (0xAB1D, 0x0000_203C),
        ] {
            assert!(super::qd_extensions_operation_route(trap_word, selector).is_none());
        }
    }

    #[test]
    fn qd_extensions_dispatch_records_exact_identity_and_rejects_wrong_parameter_size() {
        let (mut d, mut cpu, mut bus) = setup();
        d.current_trap_word = 0xAB1D;

        cpu.write_reg(Register::D0, 0x0004_0008);
        let result = d.dispatch_quickdraw(true, 0x31D, &mut cpu, &mut bus);
        assert!(result.expect("QDExtensions arm").is_ok());
        assert_eq!(
            d.current_selector_operation,
            Some(super::QD_EXTENSIONS_OPERATION_ROUTES[4].operation_id)
        );

        cpu.write_reg(Register::A7, TEST_SP);
        cpu.write_reg(Register::D0, 0x0005_0008);
        let result = d.dispatch_quickdraw(true, 0x31D, &mut cpu, &mut bus);
        assert!(result.expect("QDExtensions arm").is_ok());
        assert_eq!(d.current_selector_operation, None);
    }

    #[test]
    fn growing_region_releases_each_superseded_backing_allocation() {
        let (_d, _cpu, mut bus) = setup();
        let handle = bus.alloc(4);
        let initial_ptr = bus.alloc(super::REGION_HEADER_SIZE);
        bus.write_long(handle, initial_ptr);
        bus.write_word(initial_ptr, super::REGION_HEADER_SIZE as u16);

        let mut previous_ptr = initial_ptr;
        for edge_count in 2..64 {
            let data_words = (0..edge_count).map(|edge| edge as i16).collect::<Vec<_>>();
            assert!(TrapDispatcher::write_region(
                &mut bus,
                handle,
                Some((0, 0, 1, edge_count as i16)),
                &data_words,
            ));

            let current_ptr = bus.read_long(handle);
            assert_ne!(current_ptr, previous_ptr);
            assert_eq!(
                bus.get_alloc_size(previous_ptr),
                None,
                "relocating a growing region must release its old storage"
            );
            assert_eq!(
                bus.get_alloc_size(current_ptr),
                Some(super::REGION_HEADER_SIZE + edge_count * 2)
            );
            previous_ptr = current_ptr;
        }
    }

    fn centered_640x480_copybits_rect() -> ScreenCopyBitsRect {
        ScreenCopyBitsRect {
            src_top: 0,
            src_left: 0,
            src_bottom: 480,
            src_right: 640,
            dst_top: 60,
            dst_left: 80,
            dst_bottom: 540,
            dst_right: 720,
        }
    }

    #[test]
    fn centered_kiosk_copybits_fills_only_margins_with_active_clut_black() {
        let (mut d, _cpu, mut bus) = setup();
        let (screen_base, row_bytes, width, height, _) = d.screen_mode;
        bus.fill_bytes(screen_base, row_bytes * u32::from(height), 0x7F);
        d.menu_bar_hidden = true;
        d.device_clut.replace([[0xFFFF, 0xFFFF, 0xFFFF]; 256]);
        d.device_clut.set_entry(37, [0, 0, 0]);

        d.fill_kiosk_letterbox_for_copybits(&mut bus, centered_640x480_copybits_rect());

        assert_eq!(bus.read_byte(screen_base), 37);
        assert_eq!(
            bus.read_byte(screen_base + 300 * row_bytes + 10),
            37,
            "side margin should use the darkest active CLUT entry"
        );
        assert_eq!(
            bus.read_byte(screen_base + 300 * row_bytes + 400),
            0x7F,
            "the completed CopyBits destination must remain untouched"
        );
        assert_eq!(
            bus.read_byte(screen_base + (u32::from(height) - 1) * row_bytes + u32::from(width) - 1),
            37
        );
    }

    #[test]
    fn centered_copybits_preserves_nonuniform_application_surround() {
        let (mut d, _cpu, mut bus) = setup();
        let (screen_base, row_bytes, _width, height, _) = d.screen_mode;
        let framebuffer_len = row_bytes * u32::from(height);
        bus.fill_bytes(screen_base, framebuffer_len, 37);
        for (offset, pixel) in [
            (139 * row_bytes + 400, 0x11),
            (460 * row_bytes + 400, 0x22),
            (300 * row_bytes + 149, 0x33),
            (300 * row_bytes + 650, 0x44),
        ] {
            bus.write_byte(screen_base + offset, pixel);
        }
        let before = bus.read_bytes(screen_base, framebuffer_len as usize);
        d.menu_bar_hidden = true;
        d.device_clut.replace([[0xFFFF, 0xFFFF, 0xFFFF]; 256]);
        d.device_clut.set_entry(37, [0, 0, 0]);

        d.fill_kiosk_letterbox_for_copybits(
            &mut bus,
            ScreenCopyBitsRect {
                src_top: 0,
                src_left: 0,
                src_bottom: 320,
                src_right: 500,
                dst_top: 140,
                dst_left: 150,
                dst_bottom: 460,
                dst_right: 650,
            },
        );

        assert!(
            bus.read_bytes(screen_base, framebuffer_len as usize) == before,
            "a centered overlay must not erase a nonuniform application-painted surround"
        );
    }

    #[test]
    fn centered_kiosk_copybits_keeps_monochrome_black_margins() {
        let (mut d, _cpu, mut bus) = setup();
        let (screen_base, _, width, height, _) = d.screen_mode;
        let row_bytes = u32::from(width as u16).div_ceil(8);
        d.screen_mode.1 = row_bytes;
        d.screen_mode.4 = 1;
        bus.fill_bytes(screen_base, row_bytes * u32::from(height), 0x00);
        d.menu_bar_hidden = true;

        d.fill_kiosk_letterbox_for_copybits(&mut bus, centered_640x480_copybits_rect());

        assert_eq!(bus.read_byte(screen_base), 0xFF);
        assert_eq!(
            bus.read_byte(screen_base + 300 * row_bytes + 400 / 8),
            0x00,
            "the monochrome CopyBits destination must remain untouched"
        );
    }

    #[test]
    fn window_local_screen_copybits_uses_physical_destination_for_letterboxing() {
        // A screen-backed window PixMap keeps its origin in bounds.topLeft.
        // CopyBits receives local destination coordinates, but fullscreen
        // bookkeeping and margin clearing must describe the physical screen
        // rectangle that those coordinates address.
        // Inside Macintosh Volume I (1985), pp. I-148 and I-166.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let (screen_base, screen_row_bytes, screen_width, screen_height, _) = d.screen_mode;
        let port = 0x181000;
        d
            .current_port
            .with_mut(|current_port| *current_port = port);
        let src_pixmap = bus.alloc(50);
        let src_base = bus.alloc(512 * 342);
        let dst_pixmap = bus.alloc(50);
        let dst_pixmap_handle = bus.alloc(4);
        let src_rect = bus.alloc(8);
        let dst_rect = bus.alloc(8);

        write_pixmap_8(&mut bus, src_pixmap, src_base, 512, 342, 0);
        bus.write_long(dst_pixmap, screen_base);
        bus.write_word(dst_pixmap + 4, 0x8000 | screen_row_bytes as u16);
        bus.write_word(dst_pixmap + 6, (-129i16) as u16);
        bus.write_word(dst_pixmap + 8, (-144i16) as u16);
        bus.write_word(dst_pixmap + 10, 471);
        bus.write_word(dst_pixmap + 12, 656);
        bus.write_word(dst_pixmap + 30, 0);
        bus.write_word(dst_pixmap + 32, 8);
        bus.write_word(dst_pixmap + 34, 1);
        bus.write_word(dst_pixmap + 36, 8);
        bus.write_long(dst_pixmap + 42, 0);
        bus.write_long(dst_pixmap_handle, dst_pixmap);
        bus.write_long(port + 2, dst_pixmap_handle);
        bus.write_word(port + 6, 0xC000);
        let vis_rgn = bus.read_long(port + 24);
        let clip_rgn = bus.read_long(port + 28);
        assert!(TrapDispatcher::write_region(
            &mut bus,
            vis_rgn,
            Some((0, 0, 342, 512)),
            &[],
        ));
        assert!(TrapDispatcher::write_region(
            &mut bus,
            clip_rgn,
            Some((-32767, -32767, 32767, 32767)),
            &[],
        ));

        bus.fill_bytes(
            screen_base,
            screen_row_bytes * u32::from(screen_height),
            0x7F,
        );
        bus.fill_bytes(src_base, 512 * 342, 0x2A);
        write_rect(&mut bus, src_rect, 0, 0, 342, 512);
        write_rect(&mut bus, dst_rect, 0, 0, 342, 512);
        d.menu_bar_hidden = true;

        bus.write_long(TEST_SP, 0);
        bus.write_word(TEST_SP + 4, 0);
        bus.write_long(TEST_SP + 6, dst_rect);
        bus.write_long(TEST_SP + 10, src_rect);
        bus.write_long(TEST_SP + 14, dst_pixmap);
        bus.write_long(TEST_SP + 18, src_pixmap);
        let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());

        assert_eq!(
            d.last_screen_copybits_rect,
            Some(ScreenCopyBitsRect {
                src_top: 0,
                src_left: 0,
                src_bottom: 342,
                src_right: 512,
                dst_top: 129,
                dst_left: 144,
                dst_bottom: 471,
                dst_right: 656,
            })
        );
        assert_eq!(
            bus.read_byte(screen_base),
            255,
            "the physical top-left margin should be cleared"
        );
        assert_eq!(
            bus.read_byte(screen_base + 300 * screen_row_bytes + 400),
            0x2A,
            "the centered physical destination should remain intact"
        );
        assert_eq!((screen_width, screen_height), (800, 600));
    }

    #[test]
    fn kiosk_letterbox_ignores_fullscreen_off_center_and_menu_visible_blits() {
        let cases = [
            (
                ScreenCopyBitsRect {
                    src_top: 0,
                    src_left: 0,
                    src_bottom: 600,
                    src_right: 800,
                    dst_top: 0,
                    dst_left: 0,
                    dst_bottom: 600,
                    dst_right: 800,
                },
                true,
            ),
            (
                ScreenCopyBitsRect {
                    dst_left: 40,
                    dst_right: 680,
                    ..centered_640x480_copybits_rect()
                },
                true,
            ),
            (
                ScreenCopyBitsRect {
                    src_bottom: 240,
                    src_right: 320,
                    ..centered_640x480_copybits_rect()
                },
                true,
            ),
            (
                ScreenCopyBitsRect {
                    src_bottom: 100,
                    src_right: 100,
                    dst_top: 250,
                    dst_left: 350,
                    dst_bottom: 350,
                    dst_right: 450,
                    ..centered_640x480_copybits_rect()
                },
                true,
            ),
            (centered_640x480_copybits_rect(), false),
        ];

        for (rect, menu_bar_hidden) in cases {
            let (mut d, _cpu, mut bus) = setup();
            let (screen_base, row_bytes, _, height, _) = d.screen_mode;
            bus.fill_bytes(screen_base, row_bytes * u32::from(height), 0x7F);
            d.menu_bar_hidden = menu_bar_hidden;
            d.device_clut.replace([[0xFFFF, 0xFFFF, 0xFFFF]; 256]);
            d.device_clut.set_entry(37, [0, 0, 0]);

            d.fill_kiosk_letterbox_for_copybits(&mut bus, rect);

            assert_eq!(bus.read_byte(screen_base), 0x7F);
        }
    }

    #[test]
    fn condensed_outline_uses_plain_text_advance() {
        // Applications can overlay an outline|condense pass ($28) with a
        // plain color pass. QuickDraw's one-pixel condense adjustment cancels
        // the outline adjustment, keeping every glyph registered.
        let (mut d, _cpu, _bus) = setup();
        d.tx_face = 0x00;
        let plain = d.advance_extra();
        d.tx_face = 0x08;
        assert_eq!(d.advance_extra(), plain + 1);
        d.tx_face = 0x20;
        assert_eq!(d.advance_extra(), plain - 1);
        d.tx_face = 0x28;
        assert_eq!(d.advance_extra(), plain);
    }

    #[test]
    fn extended_face_adds_one_pixel_to_each_advance() {
        let (mut d, _cpu, _bus) = setup();
        d.tx_face = 0x00;
        let plain = d.advance_extra();
        d.tx_face = 0x40;
        assert_eq!(d.advance_extra(), plain + 1);
    }

    /// Helper: allocate a simple 10-byte region and its handle at given addresses.
    fn make_rgn(
        bus: &mut impl MemoryBus,
        rgn_addr: u32,
        handle_addr: u32,
        top: i16,
        left: i16,
        bottom: i16,
        right: i16,
    ) {
        bus.write_word(rgn_addr, 10);
        bus.write_word(rgn_addr + 2, top as u16);
        bus.write_word(rgn_addr + 4, left as u16);
        bus.write_word(rgn_addr + 6, bottom as u16);
        bus.write_word(rgn_addr + 8, right as u16);
        bus.write_long(handle_addr, rgn_addr);
    }

    fn make_complex_rgn(
        bus: &mut MacMemoryBus,
        bbox: (i16, i16, i16, i16),
        data_words: &[i16],
    ) -> u32 {
        let handle = bus.alloc(4);
        assert!(TrapDispatcher::write_region(
            bus,
            handle,
            Some(bbox),
            data_words
        ));
        handle
    }

    #[test]
    fn framergn_frames_complex_boundary_without_painting_interior() {
        // Imaging With QuickDraw (1994), pp. 3-100--3-101: FrameRgn is
        // equivalent to CopyRgn + InsetRgn + DiffRgn.  A complex region's
        // interior must therefore remain untouched.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        d
            .current_port
            .with_mut(|current_port| *current_port = 0x181000);
        d.pn_size = (1, 1);
        d.pn_pat = [0xFF; 8];
        d.pn_mode = 8; // patCopy

        let rgn = bus.alloc(4);
        let mut rows = vec![vec![10, 20]; 10];
        // A two-pixel hole makes this a genuinely complex region and gives
        // FrameRgn an interior boundary to outline as well.
        rows[5] = vec![10, 14, 16, 20];
        assert!(TrapDispatcher::write_region_from_rows(
            &mut bus, rgn, 10, &rows
        ));
        assert!(bus.read_word(bus.read_long(rgn)) > super::REGION_HEADER_SIZE as u16);

        d.draw_rgn(&mut cpu, &mut bus, rgn, ShapeOp::Frame);

        let screen = bus.read_long(0x0824);
        let pixel_is_black = |bus: &MacMemoryBus, y: u32, x: u32| {
            let byte = bus.read_byte(screen + y * 64 + x / 8);
            byte & (1 << (7 - (x % 8))) != 0
        };
        assert!(
            pixel_is_black(&bus, 10, 12),
            "outer boundary must be framed"
        );
        assert!(
            pixel_is_black(&bus, 15, 13),
            "the boundary around a complex-region hole must be framed"
        );
        assert!(
            !pixel_is_black(&bus, 12, 12),
            "FrameRgn must not paint a complex region's interior"
        );
    }

    /// Helper: write a BitMap record.
    fn write_bitmap_record(
        bus: &mut impl MemoryBus,
        bitmap_ptr: u32,
        base_addr: u32,
        row_bytes: u16,
        top: i16,
        left: i16,
        bottom: i16,
        right: i16,
    ) {
        bus.write_long(bitmap_ptr, base_addr);
        bus.write_word(bitmap_ptr + 4, row_bytes);
        bus.write_word(bitmap_ptr + 6, top as u16);
        bus.write_word(bitmap_ptr + 8, left as u16);
        bus.write_word(bitmap_ptr + 10, bottom as u16);
        bus.write_word(bitmap_ptr + 12, right as u16);
    }

    /// Helper: write a polygon record and its handle.
    /// PolyRec layout: polySize(2) + polyBBox(8) + polyPoints(4*N).
    fn make_poly(
        bus: &mut impl MemoryBus,
        poly_addr: u32,
        handle_addr: u32,
        bbox: (i16, i16, i16, i16),
        points: &[(i16, i16)],
    ) {
        let poly_size = 10 + points.len() as u32 * 4;
        bus.write_word(poly_addr, poly_size as u16);
        bus.write_word(poly_addr + 2, bbox.0 as u16);
        bus.write_word(poly_addr + 4, bbox.1 as u16);
        bus.write_word(poly_addr + 6, bbox.2 as u16);
        bus.write_word(poly_addr + 8, bbox.3 as u16);
        for (idx, (v, h)) in points.iter().enumerate() {
            let off = poly_addr + 10 + idx as u32 * 4;
            bus.write_word(off, *v as u16);
            bus.write_word(off + 2, *h as u16);
        }
        bus.write_long(handle_addr, poly_addr);
    }

    fn setup_polygon_surface(
        d: &mut TrapDispatcher,
        bus: &mut crate::memory::MacMemoryBus,
    ) -> (u32, u32) {
        let row_bytes = 64u32;
        let width = 64u16;
        let height = 64u16;
        let screen_base = bus.alloc(row_bytes * height as u32);
        bus.fill_zeros(screen_base, row_bytes * height as u32);
        bus.write_long(0x0824, screen_base);
        d.screen_mode = (screen_base, row_bytes, width, height, 8);

        const PORT_PTR: u32 = 0x181000;
        bus.write_long(PORT_PTR + 2, screen_base);
        bus.write_word(PORT_PTR + 6, row_bytes as u16);

        (screen_base, row_bytes)
    }

    fn setup_color_polygon_surface(
        d: &mut TrapDispatcher,
        cpu: &impl CpuOps,
        bus: &mut crate::memory::MacMemoryBus,
    ) -> (u32, u32) {
        let (screen_base, row_bytes) = setup_polygon_surface(d, bus);
        let a5 = cpu.read_reg(Register::A5);
        let globals = bus.read_long(a5);
        let port = bus.read_long(globals);
        let pixmap = bus.alloc(50);
        let pixmap_handle = bus.alloc(4);
        bus.fill_zeros(pixmap, 50);
        bus.write_long(pixmap_handle, pixmap);
        bus.write_long(pixmap, screen_base);
        bus.write_word(pixmap + 4, 0x8000 | row_bytes as u16);
        bus.write_word(pixmap + 6, 0);
        bus.write_word(pixmap + 8, 0);
        bus.write_word(pixmap + 10, 64);
        bus.write_word(pixmap + 12, 64);
        bus.write_word(pixmap + 32, 8);
        bus.write_word(pixmap + 34, 1);
        bus.write_word(pixmap + 36, 8);
        bus.write_long(port + 2, pixmap_handle);
        bus.write_word(port + 6, 0xC000);
        d.init_cgraf_port_defaults(port, bus);
        d
            .current_port
            .with_mut(|current_port| *current_port = port);
        (screen_base, row_bytes)
    }

    /// Allocate a minimal PixPat handle+record and seed pat1Data bytes.
    fn make_pixpat_handle(bus: &mut crate::memory::MacMemoryBus, pat1_data: [u8; 8]) -> u32 {
        let pp_handle = bus.alloc(4);
        let pp_ptr = bus.alloc(28);
        bus.write_long(pp_handle, pp_ptr);
        bus.fill_zeros(pp_ptr, 28);
        bus.write_word(pp_ptr, 1); // patType=color
        bus.write_bytes(pp_ptr + 20, &pat1_data); // pat1Data fallback pattern
        pp_handle
    }

    fn make_raw_color_pixpat_handle(bus: &mut crate::memory::MacMemoryBus) -> u32 {
        let pp_handle = bus.alloc(4);
        let pp_ptr = bus.alloc(128);
        bus.write_long(pp_handle, pp_ptr);
        bus.fill_zeros(pp_ptr, 128);

        const PAT_MAP_OFFSET: u32 = 28;
        const PAT_DATA_OFFSET: u32 = 78;
        const CTAB_OFFSET: u32 = 80;

        bus.write_word(pp_ptr, 1); // patType = color
        bus.write_long(pp_ptr + 2, PAT_MAP_OFFSET);
        bus.write_long(pp_ptr + 6, PAT_DATA_OFFSET);
        bus.write_word(pp_ptr + 14, 0xFFFF); // patXValid
        bus.write_bytes(pp_ptr + 20, &[0xAA; 8]); // fallback unused on color path

        let pixmap = pp_ptr + PAT_MAP_OFFSET;
        bus.write_word(pixmap, 0x8001); // 1 byte/row, color PixMap rowBytes flag set
        bus.write_word(pixmap + 2, 0);
        bus.write_word(pixmap + 4, 0);
        bus.write_word(pixmap + 6, 2);
        bus.write_word(pixmap + 8, 4);
        bus.write_long(pixmap + 14, 0x0048_0000); // hRes
        bus.write_long(pixmap + 18, 0x0048_0000); // vRes
        bus.write_word(pixmap + 28, 2); // pixelSize
        bus.write_word(pixmap + 30, 1); // cmpCount
        bus.write_word(pixmap + 32, 2); // cmpSize
        bus.write_long(pixmap + 38, CTAB_OFFSET);

        // Two rows of 2bpp source pixels:
        // row 0 = values 0,1,2,1; row 1 = 2,1,0,1.
        bus.write_byte(pp_ptr + PAT_DATA_OFFSET, 0x19);
        bus.write_byte(pp_ptr + PAT_DATA_OFFSET + 1, 0x91);

        let ctab = pp_ptr + CTAB_OFFSET;
        bus.write_word(ctab + 6, 2); // 3 entries
        let entries = [
            (0u16, [0x1111, 0x0000, 0x0000]),
            (1u16, [0x0000, 0x2222, 0x0000]),
            (2u16, [0x0000, 0x0000, 0x3333]),
        ];
        for (idx, (value, rgb)) in entries.iter().enumerate() {
            let entry = ctab + 8 + idx as u32 * 8;
            bus.write_word(entry, *value);
            bus.write_word(entry + 2, rgb[0]);
            bus.write_word(entry + 4, rgb[1]);
            bus.write_word(entry + 6, rgb[2]);
        }

        pp_handle
    }

    fn make_test_ctab_handle(
        bus: &mut crate::memory::MacMemoryBus,
        entries: &[[u16; 3]],
        seed: u32,
        flags: u16,
    ) -> u32 {
        let handle = bus.alloc(4);
        let ptr = bus.alloc(8 + entries.len() as u32 * 8);
        bus.write_long(handle, ptr);
        bus.write_long(ptr, seed);
        bus.write_word(ptr + 4, flags);
        bus.write_word(ptr + 6, entries.len().saturating_sub(1) as u16);
        for (index, rgb) in entries.iter().enumerate() {
            let entry = ptr + 8 + index as u32 * 8;
            bus.write_word(entry, index as u16);
            bus.write_word(entry + 2, rgb[0]);
            bus.write_word(entry + 4, rgb[1]);
            bus.write_word(entry + 6, rgb[2]);
        }
        handle
    }

    fn read_test_ctab_rgb(
        bus: &crate::memory::MacMemoryBus,
        ctab_handle: u32,
        index: u32,
    ) -> [u16; 3] {
        let ptr = bus.read_long(ctab_handle);
        let entry = ptr + 8 + index * 8;
        [
            bus.read_word(entry + 2),
            bus.read_word(entry + 4),
            bus.read_word(entry + 6),
        ]
    }

    fn read_surface_pixel(
        bus: &impl MemoryBus,
        screen_base: u32,
        row_bytes: u32,
        x: u32,
        y: u32,
    ) -> u8 {
        bus.read_byte(screen_base + y * row_bytes + x)
    }

    /// Helper: read bbox rect (top,left,bottom,right) from a region handle.
    fn read_rgn_bbox(bus: &impl MemoryBus, rgn_handle: u32) -> (i16, i16, i16, i16) {
        let rgn_ptr = bus.read_long(rgn_handle);
        (
            bus.read_word(rgn_ptr + 2) as i16,
            bus.read_word(rgn_ptr + 4) as i16,
            bus.read_word(rgn_ptr + 6) as i16,
            bus.read_word(rgn_ptr + 8) as i16,
        )
    }

    fn assert_rgn_bytes_equal(bus: &impl MemoryBus, actual_handle: u32, expected_handle: u32) {
        let actual_ptr = bus.read_long(actual_handle);
        let expected_ptr = bus.read_long(expected_handle);
        let expected_size = bus.read_word(expected_ptr) as u32;
        assert_eq!(bus.read_word(actual_ptr) as u32, expected_size);
        for offset in 0..expected_size {
            assert_eq!(
                bus.read_byte(actual_ptr + offset),
                bus.read_byte(expected_ptr + offset),
                "region byte {} should match",
                offset
            );
        }
    }

    /// Build a minimal version-1 PICT with a single paintRect opcode.
    fn write_v1_paintrect_picture(
        bus: &mut impl MemoryBus,
        pic: u32,
        pic_frame: (i16, i16, i16, i16),
        paint_rect: (i16, i16, i16, i16),
    ) {
        let mut p = pic + 10;
        bus.write_byte(p, 0x11); // versionOp
        p += 1;
        bus.write_byte(p, 0x01); // version 1
        p += 1;
        bus.write_byte(p, 0x31); // paintRect
        p += 1;
        bus.write_word(p, paint_rect.0 as u16);
        p += 2;
        bus.write_word(p, paint_rect.1 as u16);
        p += 2;
        bus.write_word(p, paint_rect.2 as u16);
        p += 2;
        bus.write_word(p, paint_rect.3 as u16);
        p += 2;
        bus.write_byte(p, 0xFF); // EndOfPicture
        p += 1;

        bus.write_word(pic, (p - pic) as u16);
        bus.write_word(pic + 2, pic_frame.0 as u16);
        bus.write_word(pic + 4, pic_frame.1 as u16);
        bus.write_word(pic + 6, pic_frame.2 as u16);
        bus.write_word(pic + 8, pic_frame.3 as u16);
    }

