    #[test]
    fn seedfill_writes_contiguous_matching_region_mask() {
        // Imaging With QuickDraw (1994), pp. 3-109..3-110:
        // SeedFill writes a 1-bit mask for the contiguous pixels reachable
        // from the seed point within the requested raw bit-image rectangle.
        let (mut d, mut cpu, mut bus) = setup();
        let src = bus.alloc(10);
        let dst = bus.alloc(10);
        let source_rows = [
            [0xFF, 0xFF],
            [0x87, 0xFF],
            [0x87, 0xFF],
            [0x87, 0xFF],
            [0xFF, 0xFF],
        ];
        for (row, bytes) in source_rows.iter().enumerate() {
            bus.write_byte(src + row as u32 * 2, bytes[0]);
            bus.write_byte(src + row as u32 * 2 + 1, bytes[1]);
            bus.write_byte(dst + row as u32 * 2, 0xAA);
            bus.write_byte(dst + row as u32 * 2 + 1, 0x55);
        }

        bus.write_word(TEST_SP, 2); // seedV
        bus.write_word(TEST_SP + 2, 2); // seedH
        bus.write_word(TEST_SP + 4, 1); // words = 16 pixels
        bus.write_word(TEST_SP + 6, 5); // height
        bus.write_word(TEST_SP + 8, 2); // dstRow
        bus.write_word(TEST_SP + 10, 2); // srcRow
        bus.write_long(TEST_SP + 12, dst);
        bus.write_long(TEST_SP + 16, src);

        let result = d.dispatch_quickdraw(true, 0x039, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 20);

        let expected_rows = [
            [0x00, 0x00],
            [0x78, 0x00],
            [0x78, 0x00],
            [0x78, 0x00],
            [0x00, 0x00],
        ];
        for (row, expected) in expected_rows.iter().enumerate() {
            assert_eq!(
                [
                    bus.read_byte(dst + row as u32 * 2),
                    bus.read_byte(dst + row as u32 * 2 + 1)
                ],
                *expected,
                "destination mask row {row}"
            );
        }
    }

    #[test]
    fn seedfill_seed_outside_rect_clears_destination_mask() {
        let (mut d, mut cpu, mut bus) = setup();
        let src = bus.alloc(4);
        let dst = bus.alloc(4);
        for i in 0..4u32 {
            bus.write_byte(src + i, 0);
            bus.write_byte(dst + i, 0xFF);
        }

        bus.write_word(TEST_SP, 0); // seedV
        bus.write_word(TEST_SP + 2, 99); // seedH outside the 16-pixel rectangle
        bus.write_word(TEST_SP + 4, 1); // words
        bus.write_word(TEST_SP + 6, 2); // height
        bus.write_word(TEST_SP + 8, 2); // dstRow
        bus.write_word(TEST_SP + 10, 2); // srcRow
        bus.write_long(TEST_SP + 12, dst);
        bus.write_long(TEST_SP + 16, src);

        let result = d.dispatch_quickdraw(true, 0x039, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 20);
        assert_eq!(bus.read_bytes(dst, 4), vec![0, 0, 0, 0]);
    }

    #[test]
    fn seedfill_five_call_composition_pops_one_hundred_bytes_total() {
        // 5 successive SeedFill dispatches with varying seedH/seedV
        // pairs (0,0)/(4,2)/(8,4)/(16,6)/(30,7) each advance A7 by 20
        // bytes, total 100 bytes. Per IM:IV IV-22 the trap pops a
        // fixed 20 bytes regardless of seed coordinate values.
        let (mut d, mut cpu, mut bus) = setup();
        let sp_before = cpu.read_reg(Register::A7);

        let seeds: [(u16, u16); 5] = [(0, 0), (4, 2), (8, 4), (16, 6), (30, 7)];
        for (i, (seed_h, seed_v)) in seeds.iter().enumerate() {
            let sp = cpu.read_reg(Register::A7);
            bus.write_word(sp, *seed_v);
            bus.write_word(sp + 2, *seed_h);
            bus.write_word(sp + 4, 2); // words
            bus.write_word(sp + 6, 8); // height
            bus.write_word(sp + 8, 4); // dstRow
            bus.write_word(sp + 10, 4); // srcRow
            bus.write_long(sp + 12, 0x320000 + (i as u32) * 0x1000);
            bus.write_long(sp + 16, 0x330000 + (i as u32) * 0x1000);

            let result = d.dispatch_quickdraw(true, 0x039, &mut cpu, &mut bus);
            assert!(result.unwrap().is_ok());
            assert_eq!(
                cpu.read_reg(Register::A7),
                sp + 20,
                "SeedFill iteration {} must pop exactly 20 bytes",
                i
            );
            cpu.write_reg(Register::A7, sp);
        }

        cpu.write_reg(Register::A7, sp_before + 100);
        assert_eq!(
            cpu.read_reg(Register::A7),
            sp_before + 100,
            "5 SeedFill calls aggregate exactly 100 bytes of stack pop"
        );
    }

    // ==================== Color Cursor Traps ====================

    #[test]
    fn getccursor_returns_handle_for_present_crsr_resource() {
        // IM:V 1986 p. V-79: GetCCursor returns a CCrsrHandle for a
        // present 'crsr' resource ID and advances A7 by the 2-byte
        // crsrID argument.
        let (mut d, mut cpu, mut bus) = setup();
        let crsr_data: Vec<u8> = (0..96).map(|i| (i as u8).wrapping_mul(7)).collect();
        d.install_test_resource(&mut bus, *b"crsr", 128, &crsr_data);
        bus.write_word(TEST_SP, 128);

        let result = d.dispatch_quickdraw(true, 0x21B, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 2);
        assert_ne!(bus.read_long(TEST_SP + 2), 0);
    }

    #[test]
    fn getccursor_promotes_compiled_crsr_offsets_to_live_handles() {
        // Imaging With QuickDraw 1994 p. 8-35: compiled 'crsr'
        // resources store offsets to the PixMap, pixel data, and color
        // table. GetCCursor returns a live CCrsrHandle whose crsrMap and
        // crsrData fields are handles.
        let (mut d, mut cpu, mut bus) = setup();
        let crsr_data = compiled_crsr_resource_2bpp();
        d.install_test_resource(&mut bus, *b"crsr", 1026, &crsr_data);
        bus.write_word(TEST_SP, 1026);

        let result = d.dispatch_quickdraw(true, 0x21B, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());

        let crsr_handle = bus.read_long(TEST_SP + 2);
        assert_ne!(crsr_handle, 0);
        let crsr_ptr = bus.read_long(crsr_handle);
        assert_ne!(crsr_ptr, 0);

        let crsr_map_handle = bus.read_long(crsr_ptr + 2);
        let crsr_data_handle = bus.read_long(crsr_ptr + 6);
        assert_ne!(
            crsr_map_handle, 0x60,
            "compiled crsrMap offset must be promoted to a live PixMapHandle"
        );
        assert_ne!(
            crsr_data_handle, 0x92,
            "compiled crsrData offset must be promoted to a live pixel-data Handle"
        );
        let pixmap_ptr = bus.read_long(crsr_map_handle);
        let data_ptr = bus.read_long(crsr_data_handle);
        assert_ne!(pixmap_ptr, 0);
        assert_ne!(data_ptr, 0);
        assert_eq!(bus.read_long(pixmap_ptr), data_ptr);
        assert_eq!(bus.read_word(pixmap_ptr + 4) & 0x3FFF, 4);
        assert_eq!(bus.read_word(pixmap_ptr + 6) as i16, 0);
        assert_eq!(bus.read_word(pixmap_ptr + 8) as i16, 0);
        assert_eq!(bus.read_word(pixmap_ptr + 10) as i16, 16);
        assert_eq!(bus.read_word(pixmap_ptr + 12) as i16, 16);
        assert_ne!(
            bus.read_long(pixmap_ptr + 42),
            0xD2,
            "compiled pmTable offset must be promoted to a ColorTable handle"
        );
    }

    #[test]
    fn getccursor_missing_resource_returns_nil() {
        // IM:V 1986 p. V-79: if the specified 'crsr' resource is not
        // found, GetCCursor returns NIL.
        let (mut d, mut cpu, mut bus) = setup();
        bus.write_word(TEST_SP, 777);

        let result = d.dispatch_quickdraw(true, 0x21B, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 2);
        assert_eq!(bus.read_long(TEST_SP + 2), 0);
    }

    #[test]
    fn getccursor_pascal_function_preserves_stack_across_five_missing_calls() {
        // Per IM:V 1986 p. V-74, each GetCCursor call obeys the Tool-
        // bit Pascal FUNCTION calling convention independently (caller
        // pre-pushes a 4-byte CCrsrHandle result slot + 2-byte crsrID
        // INTEGER, trap pops the 2-byte arg and writes the handle to
        // the result slot at the post-pop SP, caller pops the slot).
        // Across a 5-call composition with five distinct fictional
        // crsrIDs all five returned handles are NIL per the documented
        // miss-returns-NIL contract AND A7 returns to its pre-
        // composition value (5 missed 2-byte pops would cumulate to
        // 10 bytes A7 drift).
        let (mut d, mut cpu, mut bus) = setup();
        let sp_before = cpu.read_reg(Register::A7);
        let crsr_ids: [i16; 5] = [0x6FF0, 0x6FF1, 0x6FF2, 0x6FF3, 0x6FF4];
        for crsr_id in crsr_ids.iter().copied() {
            let sp = cpu.read_reg(Register::A7);
            let slot_addr = sp.wrapping_sub(6);
            bus.write_long(slot_addr, 0xDEAD_BEEF);
            bus.write_word(slot_addr + 4, crsr_id as u16);
            cpu.write_reg(Register::A7, slot_addr);

            let result = d.dispatch_quickdraw(true, 0x21B, &mut cpu, &mut bus);
            assert!(result.unwrap().is_ok());

            assert_eq!(cpu.read_reg(Register::A7), slot_addr + 2);
            assert_eq!(bus.read_long(slot_addr + 2), 0);
            cpu.write_reg(Register::A7, slot_addr + 6);
        }
        assert_eq!(
            cpu.read_reg(Register::A7),
            sp_before,
            "5-call GetCCursor composition with distinct missing crsrIDs is net A7-balanced"
        );
    }

    #[test]
    fn setccursor_consumes_ccrsrhandle_pointer_argument() {
        // IM:V 1986 p. V-80: SetCCursor is a procedure with one
        // CCrsrHandle argument and no function result.
        let (mut d, mut cpu, mut bus) = setup();
        bus.write_long(TEST_SP, 0x1234_5678);

        let result = d.dispatch_quickdraw(true, 0x21C, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
    }

    #[test]
    fn setccursor_updates_cursor_state_from_ccrsr_handle() {
        // IM:V 1986 p. V-80: SetCCursor installs the supplied color cursor
        // as the current cursor. Systemless HLE keeps the current cursor image
        // in dispatcher state so the host can render it.
        let (mut d, mut cpu, mut bus) = setup();
        let crsr_ptr = bus.alloc(96);
        let crsr_handle = bus.alloc(4);

        bus.write_long(crsr_handle, crsr_ptr);
        bus.write_word(crsr_ptr, 0x8001);
        bus.write_word(crsr_ptr + 14, 7);
        for i in 0..16u32 {
            bus.write_word(crsr_ptr + 20 + i * 2, 0x1100 | (i as u16));
            bus.write_word(crsr_ptr + 52 + i * 2, 0x2200 | (i as u16));
        }
        bus.write_word(crsr_ptr + 84, 13);
        bus.write_word(crsr_ptr + 86, -9i16 as u16);

        d.cursor_state.set_level_for_test(-1);
        bus.write_long(TEST_SP, crsr_handle);

        let result = d.dispatch_quickdraw(true, 0x21C, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
        assert_eq!(
            d.cursor_data(),
            Some((
                {
                    let mut data = [0u8; 32];
                    for i in 0..16u32 {
                        let v = 0x1100 | (i as u16);
                        data[(i as usize) * 2] = (v >> 8) as u8;
                        data[(i as usize) * 2 + 1] = (v & 0xFF) as u8;
                    }
                    data
                },
                {
                    let mut mask = [0u8; 32];
                    for i in 0..16u32 {
                        let v = 0x2200 | (i as u16);
                        mask[(i as usize) * 2] = (v >> 8) as u8;
                        mask[(i as usize) * 2 + 1] = (v & 0xFF) as u8;
                    }
                    mask
                },
                13,
                -9,
            ))
        );
        assert!(!d.cursor_visible());
    }

    #[test]
    fn setccursor_installs_color_pixels_from_promoted_ccrsr() {
        // Imaging With QuickDraw 1994 p. 8-5: on screens deeper than
        // 2bpp, a color cursor's image comes from crsrMap + crsrData,
        // with the same mask used by the one-bit fallback.
        let (mut d, mut cpu, mut bus) = setup();
        let crsr_data = compiled_crsr_resource_2bpp();
        d.install_test_resource(&mut bus, *b"crsr", 1026, &crsr_data);
        bus.write_word(TEST_SP, 1026);
        assert!(d
            .dispatch_quickdraw(true, 0x21B, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());
        let crsr_handle = bus.read_long(TEST_SP + 2);

        let sp = cpu.read_reg(Register::A7);
        bus.write_long(sp, crsr_handle);
        assert!(d
            .dispatch_quickdraw(true, 0x21C, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());

        let Some(CursorImage::Color {
            width,
            height,
            pixels_argb,
            hot_v,
            hot_h,
            ..
        }) = d.cursor()
        else {
            panic!("SetCCursor should install decoded color cursor pixels");
        };
        assert_eq!((*width, *height), (16, 16));
        assert_eq!((*hot_v, *hot_h), (15, 7));
        assert_eq!(pixels_argb[0], 0xFFFF_FFFF);
        assert_eq!(pixels_argb[1], 0xFFFF_0000);
        assert_eq!(pixels_argb[2], 0xFF00_FF00);
        assert_eq!(pixels_argb[3], 0xFF00_0000);
    }

    #[test]
    fn disposeccursor_consumes_ccrsrhandle_pointer_argument() {
        // IM:V 1986 p. V-80: DisposCCursor is a procedure with one
        // CCrsrHandle argument and no function result.
        let (mut d, mut cpu, mut bus) = setup();
        bus.write_long(TEST_SP, 0x90AB_CDEF);

        let result = d.dispatch_quickdraw(true, 0x226, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 4);
    }

    #[test]
    fn disposeccursor_releases_promoted_ccrsr_object_graph() {
        // Imaging With QuickDraw (1994), pp. 8-4–8-5 and 8-26–8-27:
        // GetCCursor promotes a compiled resource into a relocatable CCrsr
        // graph and DisposeCCursor releases that graph. The CCrsr's common
        // color-compound prefix owns crsrMap, crsrData, crsrXData, and
        // crsrXHandle; the PixMap in turn owns its color table.
        let (mut d, mut cpu, mut bus) = setup();
        let crsr_data = compiled_crsr_resource_2bpp();
        d.install_test_resource(&mut bus, *b"crsr", 1026, &crsr_data);
        bus.write_word(TEST_SP, 1026);
        assert!(d
            .dispatch_quickdraw(true, 0x21B, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());

        let crsr_handle = bus.read_long(TEST_SP + 2);
        let crsr_ptr = bus.read_long(crsr_handle);
        let crsr_map_handle = bus.read_long(crsr_ptr + 2);
        let crsr_map_ptr = bus.read_long(crsr_map_handle);
        let crsr_data_handle = bus.read_long(crsr_ptr + 6);
        let crsr_data_ptr = bus.read_long(crsr_data_handle);
        let crsr_xdata_handle = bus.read_long(crsr_ptr + 10);
        let crsr_xdata_ptr = bus.read_long(crsr_xdata_handle);
        let crsr_xhandle = bus.read_long(crsr_ptr + 16);
        let crsr_xhandle_ptr = bus.read_long(crsr_xhandle);
        let color_table_handle = bus.read_long(crsr_map_ptr + 42);
        let color_table_ptr = bus.read_long(color_table_handle);

        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, crsr_handle);

        let result = d.dispatch_quickdraw(true, 0x226, &mut cpu, &mut bus);
        assert!(result.is_some(), "DisposeCCursor should be handled");
        assert!(result.unwrap().is_ok(), "DisposeCCursor should return");
        assert_eq!(
            cpu.read_reg(Register::A7),
            TEST_SP + 4,
            "DisposeCCursor should pop one CCrsrHandle argument"
        );
        for addr in [
            crsr_handle,
            crsr_ptr,
            crsr_map_handle,
            crsr_map_ptr,
            crsr_data_handle,
            crsr_data_ptr,
            crsr_xdata_handle,
            crsr_xdata_ptr,
            crsr_xhandle,
            crsr_xhandle_ptr,
            color_table_handle,
            color_table_ptr,
        ] {
            assert!(
                bus.get_alloc_size(addr).is_none(),
                "DisposeCCursor leaked allocation at ${addr:08X}"
            );
        }
    }

