        make_rgn(&mut bus, 0x330200, 0x330300, 0, 0, 600, 800);
        bus.write_long(port + 24, 0x330100);
        bus.write_long(port + 28, 0x330300);

        d.set_current_port_state(&mut bus, &mut cpu, port, Some(gdh));
        d.bg_color = (0xFFFF, 0xFFFF, 0xFFFF);
