    fn write_bitmap_1bpp(
        bus: &mut impl MemoryBus,
        bits_ptr: u32,
        base_addr: u32,
        row_bytes: u16,
        bounds: (i16, i16, i16, i16),
    ) {
        bus.write_long(bits_ptr, base_addr);
        bus.write_word(bits_ptr + 4, row_bytes);
        write_rect(bus, bits_ptr + 6, bounds.0, bounds.1, bounds.2, bounds.3);
    }

