    #[test]
    fn test_copy_bits_skips_sentinel_ffffffff_baseaddr() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let src_bits = 0x300100u32;
        let dst_bits = 0x300200u32;
        let src_base = 0x301000u32;
        let src_rect = 0x302000u32;
        let dst_rect = 0x302010u32;

        // 1bpp source bitmap: 16 white pixels in a single row.
        bus.write_long(src_bits, src_base);
        bus.write_word(src_bits + 4, 2u16); // rowBytes
        bus.write_word(src_bits + 6, 0); // top
        bus.write_word(src_bits + 8, 0); // left
        bus.write_word(src_bits + 10, 1); // bottom
        bus.write_word(src_bits + 12, 16); // right
        bus.write_byte(src_base, 0xFF);
        bus.write_byte(src_base + 1, 0xFF);

        // Destination bitmap uses baseAddr=$FFFFFFFF sentinel.
        // Without the guard this can wrap and write low RAM.
        bus.write_long(dst_bits, u32::MAX);
        bus.write_word(dst_bits + 4, 2u16); // rowBytes
        bus.write_word(dst_bits + 6, 0); // top
        bus.write_word(dst_bits + 8, 0); // left
        bus.write_word(dst_bits + 10, 1); // bottom
        bus.write_word(dst_bits + 12, 16); // right

        write_rect(&mut bus, src_rect, 0, 0, 1, 16);
        write_rect(&mut bus, dst_rect, 0, 0, 1, 16);

        bus.write_byte(0, 0xAA);
        bus.write_byte(1, 0x55);

        bus.write_long(TEST_SP, 0); // maskRgn
        bus.write_word(TEST_SP + 4, 0u16); // mode=srcCopy
        bus.write_long(TEST_SP + 6, dst_rect);
        bus.write_long(TEST_SP + 10, src_rect);
        bus.write_long(TEST_SP + 14, dst_bits);
        bus.write_long(TEST_SP + 18, src_bits);

        let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 22);
        assert_eq!(
            bus.read_byte(0),
            0xAA,
            "CopyBits must no-op when dst baseAddr is $FFFFFFFF"
        );
        assert_eq!(
            bus.read_byte(1),
            0x55,
            "sentinel-baseAddr CopyBits must not wrap writes into low RAM"
        );
    }

    #[test]
    fn test_copy_bits_uses_low24_baseaddr_when_tagged_high_byte_points_unmapped() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let src_bits = 0x300100u32;
        let dst_pixmap = 0x300200u32;
        let src_base = 0x0030_1000u32;
        let tagged_src_base = 0x3300_0000u32 | src_base;
        let dst_base = 0x302000u32;
        let src_rect = 0x303000u32;
        let dst_rect = 0x303010u32;

        // 1bpp source bitmap with all bits set (black pixels).
        write_bitmap_record(&mut bus, src_bits, tagged_src_base, 2, 0, 0, 1, 16);
        bus.write_byte(src_base, 0xFF);
        bus.write_byte(src_base + 1, 0xFF);

        // 8bpp destination pixmap.
        write_pixmap_8(&mut bus, dst_pixmap, dst_base, 16, 1, 0);
        bus.fill_zeros(dst_base, 16);

        write_rect(&mut bus, src_rect, 0, 0, 1, 16);
        write_rect(&mut bus, dst_rect, 0, 0, 1, 16);

        bus.write_long(TEST_SP, 0);
        bus.write_word(TEST_SP + 4, 0u16); // srcCopy
        bus.write_long(TEST_SP + 6, dst_rect);
        bus.write_long(TEST_SP + 10, src_rect);
        bus.write_long(TEST_SP + 14, dst_pixmap);
        bus.write_long(TEST_SP + 18, src_bits);

        let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(
            bus.read_byte(dst_base),
            0xFF,
            "CopyBits should sample from low-24-bit source baseAddr when tagged high byte points unmapped"
        );
        assert_eq!(bus.read_byte(dst_base + 15), 0xFF);
    }

    #[test]
    fn copy_bits_8bpp_srcor_colorizes_black_source_and_preserves_white_source() {
        // Imaging With QuickDraw 1994, p. 4-33: for colored pixels, srcOr
        // applies the foreground color where the source is black and leaves
        // destination pixels alone where the source is white.
        let (mut d, mut cpu, mut bus) = setup_with_port();
        d.fg_color = (0xFFFF, 0xFFFF, 0xFFFF);
        d.bg_color = (0, 0, 0);

        let src_pixmap = 0x300100u32;
        let dst_pixmap = 0x300200u32;
        let src_base = 0x301000u32;
        let dst_base = 0x302000u32;
        write_pixmap_8(&mut bus, src_pixmap, src_base, 4, 4, 0);
        write_pixmap_8(&mut bus, dst_pixmap, dst_base, 4, 4, 0);

        // Black source pixels form a top-left bracket on a white source
        // background. srcOr should draw only those bracket strokes.
        bus.write_bytes(
            src_base,
            &[
                255, 255, 255, 255, //
                255, 0, 0, 0, //
                255, 0, 0, 0, //
                255, 0, 0, 0,
            ],
        );
        bus.write_bytes(dst_base, &[255; 16]);

        let src_rect = bus.alloc(8);
        let dst_rect = bus.alloc(8);
        write_rect(&mut bus, src_rect, 0, 0, 4, 4);
        write_rect(&mut bus, dst_rect, 0, 0, 4, 4);

        bus.write_long(TEST_SP, 0);
        bus.write_word(TEST_SP + 4, 1u16); // srcOr
        bus.write_long(TEST_SP + 6, dst_rect);
        bus.write_long(TEST_SP + 10, src_rect);
        bus.write_long(TEST_SP + 14, dst_pixmap);
        bus.write_long(TEST_SP + 18, src_pixmap);

        let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());

        assert_eq!(
            bus.read_bytes(dst_base, 16),
            vec![
                0, 0, 0, 0, //
                0, 255, 255, 255, //
                0, 255, 255, 255, //
                0, 255, 255, 255,
            ],
            "8bpp srcOr should render bracket strokes through the foreground color without copying the source rectangle's white background"
        );
    }

    #[test]
    fn copy_bits_rgbdirect_sources_map_into_every_indexed_depth() {
        for (src_bits, source_bytes) in [
            (16u16, vec![0x7C, 0x00, 0x03, 0xE0]),
            (32u16, vec![0x00, 0xFF, 0x00, 0x00, 0x00, 0x00, 0xFF, 0x00]),
        ] {
            for (dst_bits, expected) in [(2u16, vec![0x60u8]), (4, vec![0x12]), (8, vec![1, 2])] {
                let (mut d, mut cpu, mut bus) = setup_with_port();
                let src_pixmap = 0x306100u32;
                let dst_pixmap = 0x306200u32;
                let src_base = 0x307000u32;
                let dst_base = 0x308000u32;
                let dst_ctab_handle = 0x309000u32;
                let src_rect = 0x30A000u32;
                let dst_rect = 0x30A010u32;

                write_direct_pixmap(&mut bus, src_pixmap, src_base, 2, 1, src_bits);
                write_color_table(
                    &mut bus,
                    dst_ctab_handle,
                    0x1234_5678,
                    &[
                        (0, 0xFFFF, 0xFFFF, 0xFFFF),
                        (1, 0xFFFF, 0, 0),
                        (2, 0, 0xFFFF, 0),
                        ((1u16 << dst_bits) - 1, 0, 0, 0),
                    ],
                );
                let row_bytes = (2 * u32::from(dst_bits)).div_ceil(8) as u16;
                write_pixmap_indexed(
                    &mut bus,
                    dst_pixmap,
                    dst_base,
                    row_bytes,
                    2,
                    1,
                    dst_bits,
                    dst_ctab_handle,
                );
                bus.write_bytes(src_base, &source_bytes);
                bus.write_byte(dst_base, 0);
                write_rect(&mut bus, src_rect, 0, 0, 1, 2);
                write_rect(&mut bus, dst_rect, 0, 0, 1, 2);
                bus.write_long(TEST_SP, 0);
                bus.write_word(TEST_SP + 4, 0);
                bus.write_long(TEST_SP + 6, dst_rect);
                bus.write_long(TEST_SP + 10, src_rect);
                bus.write_long(TEST_SP + 14, dst_pixmap);
                bus.write_long(TEST_SP + 18, src_pixmap);

                let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
                assert!(result.unwrap().is_ok());
                assert_eq!(
                    bus.read_bytes(dst_base, expected.len()),
                    expected,
                    "{src_bits}-bit RGBDirect into {dst_bits}-bit indexed"
                );
            }
        }

        for (src_bits, source_bytes) in [
            (16u16, vec![0x00, 0x00, 0x7F, 0xFF]),
            (32u16, vec![0, 0, 0, 0, 0, 0xFF, 0xFF, 0xFF]),
        ] {
            let (mut d, mut cpu, mut bus) = setup_with_port();
            let src_pixmap = 0x306100u32;
            let dst_pixmap = 0x306200u32;
            let src_base = 0x307000u32;
            let dst_base = 0x308000u32;
            let src_rect = 0x30A000u32;
            let dst_rect = 0x30A010u32;
            write_direct_pixmap(&mut bus, src_pixmap, src_base, 2, 1, src_bits);
            write_pixmap_indexed(&mut bus, dst_pixmap, dst_base, 1, 2, 1, 1, 0);
            bus.write_bytes(src_base, &source_bytes);
            bus.write_byte(dst_base, 0);
            write_rect(&mut bus, src_rect, 0, 0, 1, 2);
            write_rect(&mut bus, dst_rect, 0, 0, 1, 2);
            bus.write_long(TEST_SP, 0);
            bus.write_word(TEST_SP + 4, 0);
            bus.write_long(TEST_SP + 6, dst_rect);
            bus.write_long(TEST_SP + 10, src_rect);
            bus.write_long(TEST_SP + 14, dst_pixmap);
            bus.write_long(TEST_SP + 18, src_pixmap);
            let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
            assert!(result.unwrap().is_ok());
            assert_eq!(bus.read_byte(dst_base), 0x80);
        }
    }

    #[test]
    fn copy_bits_rgbdirect_transparent_and_boolean_modes_use_rgb_values() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        d.fg_color = (0, 0, 0);
        d.bg_color = (0xFFFF, 0xFFFF, 0xFFFF);
        let src_pixmap = 0x306100u32;
        let dst_pixmap = 0x306200u32;
        let src_base = 0x307000u32;
        let dst_base = 0x308000u32;
        let src_rect = 0x30A000u32;
        let dst_rect = 0x30A010u32;
        write_direct_pixmap(&mut bus, src_pixmap, src_base, 2, 1, 32);
        write_pixmap_8(&mut bus, dst_pixmap, dst_base, 2, 1, 0);
        bus.write_bytes(src_base, &[0, 0xFF, 0xFF, 0xFF, 0, 0, 0, 0]);
        bus.write_bytes(dst_base, &[42, 0]);
        write_rect(&mut bus, src_rect, 0, 0, 1, 2);
        write_rect(&mut bus, dst_rect, 0, 0, 1, 2);
        bus.write_long(TEST_SP, 0);
        bus.write_word(TEST_SP + 4, 36);
        bus.write_long(TEST_SP + 6, dst_rect);
        bus.write_long(TEST_SP + 10, src_rect);
        bus.write_long(TEST_SP + 14, dst_pixmap);
        bus.write_long(TEST_SP + 18, src_pixmap);
        assert!(d
            .dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());
        assert_eq!(bus.read_bytes(dst_base, 2), vec![42, 255]);

        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_bytes(dst_base, &[42, 42]);
        bus.write_word(TEST_SP + 4, 1);
        assert!(d
            .dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus)
            .unwrap()
            .is_ok());
        assert_eq!(bus.read_bytes(dst_base, 2), vec![42, 255]);
    }

    #[test]
    fn copy_bits_4bpp_srcor_uses_color_tables_and_preserves_white_source() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        d.fg_color = (0, 0, 0);
        d.bg_color = (0xFFFF, 0xFFFF, 0xFFFF);

        let src_pixmap = 0x306100u32;
        let dst_pixmap = 0x306200u32;
        let src_base = 0x307000u32;
        let dst_base = 0x308000u32;
        let src_ctab_handle = 0x309000u32;
        let dst_ctab_handle = 0x30A000u32;
        let src_rect = 0x30B000u32;
        let dst_rect = 0x30B010u32;

        write_color_table(
            &mut bus,
            src_ctab_handle,
            0x1111_1111,
            &[(0, 0xFFFF, 0xFFFF, 0xFFFF), (15, 0x0000, 0x0000, 0x0000)],
        );
        write_color_table(
            &mut bus,
            dst_ctab_handle,
            0x2222_2222,
            &[
                (0, 0xFFFF, 0xFFFF, 0xFFFF),
                (13, 0x8000, 0x8000, 0x8000),
                (15, 0x0000, 0x0000, 0x0000),
            ],
        );
        write_pixmap_indexed(&mut bus, src_pixmap, src_base, 1, 2, 1, 4, src_ctab_handle);
        write_pixmap_indexed(&mut bus, dst_pixmap, dst_base, 1, 2, 1, 4, dst_ctab_handle);
        bus.write_byte(src_base, 0x0F);
        bus.write_byte(dst_base, 0xDD);
        write_rect(&mut bus, src_rect, 0, 0, 1, 2);
        write_rect(&mut bus, dst_rect, 0, 0, 1, 2);

        bus.write_long(TEST_SP, 0);
        bus.write_word(TEST_SP + 4, 1u16);
        bus.write_long(TEST_SP + 6, dst_rect);
        bus.write_long(TEST_SP + 10, src_rect);
        bus.write_long(TEST_SP + 14, dst_pixmap);
        bus.write_long(TEST_SP + 18, src_pixmap);

        let result = d.dispatch_quickdraw(true, 0x0EC, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        assert_eq!(
            bus.read_byte(dst_base),
            0xDF,
            "4bpp srcOr should preserve white source pixels and apply black through the destination CTable"
        );
    }

    #[test]
