    #[test]
    fn rgb_fore_color_resolves_against_an_offscreen_pixmap_color_table() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let port = 0x181000u32;
        let pixmap_handle = bus.alloc(4);
        let pixmap = bus.alloc(50);
        let pixels = bus.alloc(8);
        let ctab_handle = bus.alloc(4);
        let ctab = bus.alloc(8 + 256 * 8);
        bus.write_long(pixmap_handle, pixmap);
        bus.write_long(ctab_handle, ctab);
        bus.fill_zeros(pixmap, 50);
        bus.fill_zeros(ctab, 8 + 256 * 8);
        bus.write_long(pixmap, pixels);
        bus.write_word(pixmap + 4, 0x8008);
        bus.write_word(pixmap + 10, 1);
        bus.write_word(pixmap + 12, 8);
        bus.write_word(pixmap + 32, 8);
        bus.write_word(pixmap + 34, 1);
        bus.write_word(pixmap + 36, 8);
        bus.write_long(pixmap + 42, ctab_handle);
        bus.write_word(ctab + 6, 255);
        for index in 0..256u32 {
            bus.write_word(ctab + 8 + index * 8, index as u16);
        }
        let green = [0x0000, 0x9900, 0x0000];
        let green_entry = ctab + 8 + 23 * 8;
        bus.write_word(green_entry + 2, green[0]);
        bus.write_word(green_entry + 4, green[1]);
        bus.write_word(green_entry + 6, green[2]);

        bus.write_long(port + 2, pixmap_handle);
        bus.write_word(port + 6, 0xC000);
        d.set_current_port_state(&mut bus, &mut cpu, port, None);
        d.device_clut.replace([[0, 0, 0]; 256]);
        d.device_clut.set_entry(0, green);

        let color = bus.alloc(6);
        bus.write_word(color, green[0]);
        bus.write_word(color + 2, green[1]);
        bus.write_word(color + 4, green[2]);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, color);

        let result = d.dispatch_quickdraw(true, 0x214, &mut cpu, &mut bus);

        assert!(result.unwrap().is_ok());
        assert_eq!(bus.read_long(port + 80), 23);
    }

    #[test]
    fn port_snapshot_restores_legacy_and_resolved_colors_after_nested_drawing() {
        let (mut d, mut cpu, mut bus) = setup_with_port();
        let (screen, row_bytes) = setup_color_polygon_surface(&mut d, &cpu, &mut bus);
        let port = *d.current_port;
        d.set_current_port_state(&mut bus, &mut cpu, port, None);
        d.device_clut.with_mut(|clut| *clut = TrapDispatcher::standard_mac_8bpp_clut());
        let rect = 0x300000;
        write_rect(&mut bus, rect, 10, 10, 12, 12);

        // Newly initialized CGrafPorts still carry the legacy blackColor and
        // whiteColor values. A nested callback resolves both fields.
        let legacy = d.capture_current_port_state(&bus);
        d.resolve_current_port_color_pixels(&mut bus, true, true, false);
        let resolved = d.capture_current_port_state(&bus);
        d.restore_current_port_state(&mut bus, &mut cpu, &legacy);
        bus.write_long(TEST_SP, rect);
        d.dispatch_quickdraw(true, 0x0A2, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        let pixel = bus.read_byte(screen + 10 * row_bytes + 10);
        assert_eq!(
            d.device_clut[pixel as usize],
            [0, 0, 0],
            "restored black must not become palette entry 33"
        );

        // Restoring an already resolved snapshot must keep exact pixel values
        // even when the palette changes while another dialog is active.
        let fg_pixel = u32::from_be_bytes(resolved.port_state_bytes[48..52].try_into().unwrap());
        d.device_clut.with_mut(|clut| clut[fg_pixel as usize] = [0xFFFF, 0, 0]);
        d.restore_current_port_state(&mut bus, &mut cpu, &resolved);
        cpu.write_reg(Register::A7, TEST_SP);
        bus.write_long(TEST_SP, rect);
        d.dispatch_quickdraw(true, 0x0A2, &mut cpu, &mut bus)
            .unwrap()
            .unwrap();
        assert_eq!(bus.read_byte(screen + 10 * row_bytes + 10), fg_pixel as u8);
        assert_eq!(d.resolved_port_color_fields.get(&port).copied(), Some(3));
    }

