    // ==================== Color Icon Traps ====================

    fn make_test_cicn_resource(mask_byte: u8, bmap_byte: u8, pixel_byte: u8) -> Vec<u8> {
        // Minimal 1-row, 8-pixel CIcon record payload:
        // CIcon header (82 bytes) + mask byte + bmap byte +
        // ColorTable (16 bytes for ctSize=0) + pixel byte.
        let mut data = vec![0u8; 101];

        // iconPMap (offset 0)
        data[4] = 0x00;
        data[5] = 0x01; // rowBytes
        data[10] = 0x00;
        data[11] = 0x01; // bounds.bottom = 1
        data[12] = 0x00;
        data[13] = 0x08; // bounds.right = 8
        data[32] = 0x00;
        data[33] = 0x01; // pixelSize = 1

        // iconMask BitMap (offset 50)
        data[54] = 0x00;
        data[55] = 0x01; // rowBytes
        data[60] = 0x00;
        data[61] = 0x01; // bounds.bottom = 1
        data[62] = 0x00;
        data[63] = 0x08; // bounds.right = 8

        // iconBMap BitMap (offset 64)
        data[68] = 0x00;
        data[69] = 0x01; // rowBytes
        data[74] = 0x00;
        data[75] = 0x01; // bounds.bottom = 1
        data[76] = 0x00;
        data[77] = 0x08; // bounds.right = 8

        // iconData handle (offset 78) intentionally zero.

        // iconMaskData + iconBMapData
        data[82] = mask_byte;
        data[83] = bmap_byte;

        // ColorTable header at offset 84:
        // ctSeed(4), ctFlags(2), ctSize(2). ctSize = 0 => 1 entry.
        data[90] = 0x00;
        data[91] = 0x00;

        // First ColorSpec entry (offset 92..99) left as zeroes.
        data[100] = pixel_byte; // inline pixel data
        data
    }

    fn make_test_cicn_resource_4bpp(pixel_bytes: [u8; 2], entries: &[[u16; 3]; 16]) -> Vec<u8> {
        // Minimal 1-row, 4-pixel, 4bpp CIcon record payload:
        // CIcon header (82 bytes) + 1-byte mask + 1-byte bmap +
        // ColorTable (16 entries) + 2 bytes of packed pixel data.
        let mut data = vec![0u8; 222];

        // iconPMap (offset 0)
        data[4] = 0x80;
        data[5] = 0x02; // rowBytes = 2, PixMap flag set
        data[10] = 0x00;
        data[11] = 0x01; // bounds.bottom = 1
        data[12] = 0x00;
        data[13] = 0x04; // bounds.right = 4
        data[32] = 0x00;
        data[33] = 0x04; // pixelSize = 4

        // iconMask BitMap (offset 50)
        data[54] = 0x00;
        data[55] = 0x01; // rowBytes
        data[60] = 0x00;
        data[61] = 0x01; // bounds.bottom = 1
        data[62] = 0x00;
        data[63] = 0x04; // bounds.right = 4

        // iconBMap BitMap (offset 64)
        data[68] = 0x00;
        data[69] = 0x01; // rowBytes
        data[74] = 0x00;
        data[75] = 0x01; // bounds.bottom = 1
        data[76] = 0x00;
        data[77] = 0x04; // bounds.right = 4

        data[82] = 0xF0; // mask: first four pixels opaque

        // ColorTable header at offset 84:
        // ctSeed(4), ctFlags(2), ctSize(2). ctSize = 15 => 16 entries.
        data[90] = 0x00;
        data[91] = 0x0F;
        for (i, rgb) in entries.iter().enumerate() {
            let entry = 92 + i * 8;
            data[entry] = 0;
            data[entry + 1] = i as u8;
            data[entry + 2..entry + 4].copy_from_slice(&rgb[0].to_be_bytes());
            data[entry + 4..entry + 6].copy_from_slice(&rgb[1].to_be_bytes());
            data[entry + 6..entry + 8].copy_from_slice(&rgb[2].to_be_bytes());
        }

        data[220] = pixel_bytes[0];
        data[221] = pixel_bytes[1];
        data
    }

