        // NIL when the requested 'cicn' resource cannot be found.
        let (mut d, mut cpu, mut bus) = setup();
        bus.write_word(TEST_SP, 777);

        let result = d.dispatch_quickdraw(true, 0x21E, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
