    #[test]
    fn get_ctable_reloads_a_registered_custom_resource() {
        let (mut d, mut cpu, mut bus) = setup();
        let mut resource = vec![0; 16];
        resource[6..8].copy_from_slice(&0u16.to_be_bytes());
        resource[8..10].copy_from_slice(&7u16.to_be_bytes());
        resource[10..12].copy_from_slice(&0x1234u16.to_be_bytes());
        resource[12..14].copy_from_slice(&0x5678u16.to_be_bytes());
        resource[14..16].copy_from_slice(&0x9ABCu16.to_be_bytes());
        let original = d.install_test_resource(&mut bus, *b"clut", 1000, &resource);
        d.with_resource_file_mut_for_test(0, |file| {
            file.loaded.insert((*b"clut", 1000), 0);
        })
        .unwrap();
        bus.free(original);
        bus.write_word(TEST_SP, 1000);

        let result = d.dispatch_quickdraw(true, 0x218, &mut cpu, &mut bus);

        assert!(result.unwrap().is_ok());
        let handle = bus.read_long(TEST_SP + 2);
        assert_ne!(handle, 0);
        let table = bus.read_long(handle);
        assert_eq!(bus.read_word(table + 6), 0);
        assert_eq!(bus.read_word(table + 8), 7);
        assert_eq!(bus.read_word(table + 10), 0x1234);
        assert_eq!(bus.read_word(table + 12), 0x5678);
        assert_eq!(bus.read_word(table + 14), 0x9ABC);
    }

    #[test]
    fn get_new_palette_reloads_a_lazily_seeded_pltt_resource() {
        // Lazy resource seeding leaves never-touched resources in the map
        // as IM-style empty handles: entry present, pointer NULL (IM: More
        // Macintosh Toolbox 1-84 -- SetResLoad / empty handles). Toolbox
        // getters emulate GetResource with ResLoad TRUE, which "reads the
        // resource into memory if it's not already in memory" (IM:MMT
        // 1-17), so GetNewPalette must fault the data in rather than
        // report the palette missing. An application that checks its
        // palette at launch exits when GetNewPalette(0) returns NIL for
        // its lazily-seeded 'pltt'.
        let (mut d, mut cpu, mut bus) = setup();
        let mut resource = vec![0u8; 32];
        resource[6..8].copy_from_slice(&1u16.to_be_bytes()); // pmEntries = 1
        resource[16..18].copy_from_slice(&0x1234u16.to_be_bytes());
        resource[18..20].copy_from_slice(&0x5678u16.to_be_bytes());
        resource[20..22].copy_from_slice(&0x9ABCu16.to_be_bytes());
        let original = d.install_test_resource(&mut bus, *b"pltt", 700, &resource);
        d.with_resource_file_mut_for_test(0, |file| {
            file.loaded.insert((*b"pltt", 700), 0);
        })
        .unwrap();
        bus.free(original);
        bus.write_word(TEST_SP, 700);

        let result = d.dispatch_quickdraw(true, 0x292, &mut cpu, &mut bus);

        assert!(result.unwrap().is_ok());
        assert_eq!(cpu.read_reg(Register::A7), TEST_SP + 2);
        assert_ne!(
            bus.read_long(TEST_SP + 2),
            0,
            "GetNewPalette must reload an empty-handle 'pltt' resource"
        );
    }

    #[test]
    fn test_get_ctable_four_returns_standard_sixteen_color_table() {
        let (mut d, mut cpu, mut bus) = setup();
        bus.write_word(TEST_SP, 4);
        let result = d.dispatch_quickdraw(true, 0x218, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());

        let handle = bus.read_long(TEST_SP + 2);
        let ctab = bus.read_long(handle);
        assert_eq!(bus.read_long(ctab), 4);
        assert_eq!(bus.read_word(ctab + 6), 15);
        let dark_green = ctab + 8 + 9 * 8;
        assert_eq!(bus.read_word(dark_green + 2), 0x0000);
        assert_eq!(bus.read_word(dark_green + 4), 0x8000);
        assert_eq!(bus.read_word(dark_green + 6), 0x11B0);
        let black = ctab + 8 + 15 * 8;
        assert_eq!(bus.read_word(black + 2), 0);
        assert_eq!(bus.read_word(black + 4), 0);
        assert_eq!(bus.read_word(black + 6), 0);
    }

    /// When the supplied CLUT DIFFERS from the GDevice CTab's CLUT, a
    /// fresh counter seed must be assigned (not the GDevice seed) so that
    /// CopyBits correctly translates across the palette mismatch.
    #[test]
    fn test_new_gworld_style_ctab_uses_fresh_seed_on_content_mismatch() {
        let (mut d, _cpu, mut bus) = setup();
        let _gdh = d.ensure_main_gdevice(&mut bus);
        let mut altered = TrapDispatcher::standard_mac_8bpp_clut();
        altered[42] = [0xABCD, 0xABCD, 0xABCD]; // diverge on one entry
        let counter_before = d.next_ct_seed;
        let handle = d.allocate_color_table_handle_with_clut(&mut bus, 8, &altered, 0x8000);
        let ptr = bus.read_long(handle);
        let got_seed = bus.read_long(ptr);
        assert_eq!(got_seed, counter_before);
        assert_ne!(got_seed, 8, "mismatched CLUT must NOT inherit GDevice seed");
    }

    // UnionRect empty-source handling per IM:I I-176.

    fn union_rect(s1: (i16, i16, i16, i16), s2: (i16, i16, i16, i16)) -> (i16, i16, i16, i16) {
        let (mut d, mut cpu, mut bus) = setup();
        let s1_ptr = 0x300000u32;
        let s2_ptr = 0x300010u32;
        let dst_ptr = 0x300020u32;
        write_rect(&mut bus, s1_ptr, s1.0, s1.1, s1.2, s1.3);
        write_rect(&mut bus, s2_ptr, s2.0, s2.1, s2.2, s2.3);
        let sp = TEST_SP - 12;
        cpu.write_reg(Register::A7, sp);
        bus.write_long(sp, dst_ptr);
        bus.write_long(sp + 4, s2_ptr);
        bus.write_long(sp + 8, s1_ptr);
        let result = d.dispatch_quickdraw(true, 0x0AB, &mut cpu, &mut bus);
        assert!(result.unwrap().is_ok());
        (
            bus.read_word(dst_ptr) as i16,
            bus.read_word(dst_ptr + 2) as i16,
            bus.read_word(dst_ptr + 4) as i16,
            bus.read_word(dst_ptr + 6) as i16,
        )
    }

    #[test]
    fn unionrect_empty_src1_returns_src2() {
        let result = union_rect((0, 0, 0, 0), (10, 20, 30, 40));
        assert_eq!(result, (10, 20, 30, 40));
    }

    #[test]
    fn unionrect_empty_src2_returns_src1() {
        let result = union_rect((10, 20, 30, 40), (5, 5, 5, 5));
        assert_eq!(result, (10, 20, 30, 40));
    }

    #[test]
    fn unionrect_both_nonempty_bounding_box() {
        let result = union_rect((10, 20, 30, 40), (15, 50, 35, 80));
        assert_eq!(result, (10, 20, 35, 80));
    }

    #[test]
    fn unionrect_both_empty_returns_zero_rect() {
        let result = union_rect((0, 0, 0, 0), (5, 5, 5, 5));
        assert_eq!(result, (0, 0, 0, 0));
    }

    // CharExtra ($AA23) — Color QuickDraw Tool-bit Pascal PROCEDURE
    // per IM:V 1986 p. V-77. Five successive CharExtra dispatches with
    // distinct Fixed values must each pop their 4-byte Fixed argument and
    // cumulatively leave A7 unchanged across the 5-call C-level
    // composition.
    #[test]
    fn charextra_pascal_procedure_preserves_stack_across_five_calls() {
        let (mut d, mut cpu, mut bus) = setup();
        let sp_pre = cpu.read_reg(Register::A7);
        // Distinct Fixed values: 0.0, 1.0, 2.0, -1.0, 0.5
        let values: [u32; 5] = [0x00000000, 0x00010000, 0x00020000, 0xFFFF0000, 0x00008000];
        for &value in &values {
            let sp = cpu.read_reg(Register::A7);
            cpu.write_reg(Register::A7, sp - 4);
            bus.write_long(sp - 4, value);
            let result = d.dispatch_quickdraw(true, 0x223, &mut cpu, &mut bus);
            assert!(result.unwrap().is_ok());
        }
        assert_eq!(cpu.read_reg(Register::A7), sp_pre);
    }

    // SetDeskCPat ($AA47) — Window Manager Tool-bit Pascal PROCEDURE
    // per IM:V 1986 p. V-210. Five successive SetDeskCPat(NIL)
    // dispatches must each pop their 4-byte PixPatHandle argument and
    // cumulatively leave A7 unchanged across the 5-call C-level
